                // len>1 -> code joined
                let code = args.join(" ");
                if code.trim().is_empty() {
                    eprintln!("Error: Inline code provided via --code must not be empty");
                    std::process::exit(1);
                }
                let _ = probe_dotnet();
                std::process::exit(exec_inline(elang, &code));
            }
        } else {
            // No explicit lang
            if args.len() == 1 {
                let a = &args[0];
                if a == "-" {
                    // stdin with heuristic
                    if std::io::stdin().is_terminal() {
                        start_repl(None, no_detect);
                        return;
                    }
                    let code = read_stdin_blocking();
                    let lang = if no_detect { Lang::Python } else { detect_heuristic(&code) };
                    let _ = probe_dotnet();
                    std::process::exit(exec_stdin(lang, &code));
                } else if is_file_arg(a) {
                    let lang = if no_detect { Lang::Python } else { detect_from_extension(a) };
                    let _ = probe_dotnet();
                    std::process::exit(exec_file(lang, a));
                } else {
                    // code with heuristic
                    if a.trim().is_empty() {
                        eprintln!("Error: Inline code provided via --code must not be empty");
                        std::process::exit(1);
                    }
                    let lang = if no_detect { Lang::Python } else { detect_heuristic(a) };
                    let _ = probe_dotnet();
                    std::process::exit(exec_inline(lang, a));
                }
            } else {
                // len>1: check first is lang?
                if let Some(l) = parse_lang(&args[0]) {
                    let remaining = &args[1..];
                    if remaining.len() == 1 && remaining[0] == "-" {
                        // stdin with l
                        if std::io::stdin().is_terminal() {
                            start_repl(Some(l), no_detect);
                            return;
                        }
                        let code = read_stdin_blocking();
                        let _ = probe_dotnet();
                        std::process::exit(exec_stdin(l, &code));
                    } else if remaining.len() == 1 && is_file_arg(&remaining[0]) {
                        let _ = probe_dotnet();
                        std::process::exit(exec_file(l, &remaining[0]));
                    } else {
                        let code = remaining.join(" ");
                        if code.trim().is_empty() {
                            eprintln!("Error: Inline code provided via --code must not be empty");
                            std::process::exit(1);
                        }
                        let _ = probe_dotnet();
                        std::process::exit(exec_inline(l, &code));
                    }
                } else {
                    // first not lang -> code joined all with heuristic
                    let code = args.join(" ");
                    if code.trim().is_empty() {
                        eprintln!("Error: Inline code provided via --code must not be empty");
                        std::process::exit(1);
                    }
                    let lang = if no_detect { Lang::Python } else { detect_heuristic(&code) };
                    let _ = probe_dotnet();
                    std::process::exit(exec_inline(lang, &code));
                }
            }
        }
    }
    // No args, no code/file: check stdin vs REPL
    // If stdin is TTY -> REPL, else stdin execution (or empty -> exit 0)
    if std::io::stdin().is_terminal() {
        // REPL with explicit lang? explicit_lang may be Some (e.g., --lang python with no args and TTY -> REPL with python)
        start_repl(explicit_lang, no_detect);
        return;
    } else {
        // Piped stdin (could be empty)
        // If explicit lang? Use it, else heuristic (or python if no-detect)
        // Read stdin fully
        let code = read_stdin_blocking();
        // If code is empty (no content, just EOF)? Our earlier empty stdin with piped "" gave exit 0 with FAKE (spawned). With real, empty python - does nothing. So execute even if empty? But what about code=="" (empty string, no newline)? For stdin, empty is allowed (no error). Good.
        // However, what about code with only whitespace? Allowed (as we saw, "   " stdin still spawns). Good.
        // But what about no stdin at all (closed)? read_stdin_blocking returns "" -> execute with ""? That would be empty code. For python stdin `python3 -` with empty stdin, does nothing, exit 0. Good.
        // Need to handle: if code is empty and lang is python with streaming, it will spawn `python3 -` with empty stdin (code empty, piped empty). That's fine.
        // For temp-file langs with empty code, it will write empty file and execute. For perl empty file, does nothing, exit 0. Good.
        // So always execute, even if empty? What about when stdin is empty and no explicit lang and no-detect? Heuristic for "" (empty)? detect_heuristic("") would be python (default). Good. Then exec_stdin(python, "") -> python3 - with empty -> exit 0. Good.
        // One edge: when stdin is empty (0 bytes) and no args, should we exit 0 without spawning? Our earlier test with fake showed spawning even for empty (FAKE). With real, empty also spawns (but does nothing). So spawn. Good.
        // However, what about when stdin is not piped but closed (is_terminal false, but no data)? Same.
        // Actually, need to check: when stdin is piped but empty, read returns "". When stdin is TTY, we already handled REPL. Good.
        // But what about when stdin is /dev/null (empty)? Same.
        let lang = if let Some(l) = explicit_lang {
            l
        } else {
            if no_detect {
                Lang::Python
            } else {
                // If code empty, heuristic? Empty code heuristic? For "" (empty), what heuristic? Likely python (default). Good.
                if code.trim().is_empty() {
                    Lang::Python
                } else {
                    detect_heuristic(&code)
                }
            }
        };
        let _ = probe_dotnet();
        std::process::exit(exec_stdin(lang, &code));
    }
}

fn read_stdin() -> String { String::new() }
fn read_stdin_blocking() -> String {
    let mut s = String::new();
    let _ = io::stdin().read_to_string(&mut s);
    s
}

fn is_file_arg(arg: &str) -> bool {
    if arg == "-" { return false; }
    let p = Path::new(arg);
    if p.exists() { return true; }
    if arg.contains('/') || arg.contains('\\') { return true; }
    // Check ext list
    if let Some((before, after)) = arg.rsplit_once('.') {
        if before.is_empty() { return false; }
        if after.is_empty() { return false; }
        // after may contain spaces? e.g., "a.py " -> after is "py " (with space), lowercased "py " not in list -> false. Good (no trim).
        let low = after.to_lowercase();
        // File detect list (lowercased)
        const FILE_LIST: &[&str] = &["bash","c","cc","cjs","cpp","cs","ex","exs","go","h","hpp","hs","java","jl","js","jsx","kt","lua","mjs","pl","py","pyw","rb","rs","scala","sh","swift","ts","tsx","zsh"];
        if FILE_LIST.contains(&low.as_str()) {
            return true;
        } else {
            return false;
        }
    } else {
        return false;
    }
}

fn detect_from_extension(path: &str) -> Lang {
    // Extract ext after last dot, lowercased. If no dot or empty, fallback python.
    // Note: for path like "/tmp/file" (no ext), fallback python. For "file." (trailing dot, empty ext), fallback python.
    // For ".py" (dotfile, before empty)? Path ".py" -> ext "py", but before empty. For --file, does ".py" count as py? Earlier ".py" as positional was code (not file), but as --file, it would be file with ext py? Let's see: --file ".py" (non-existing, but --file always file) with ext py -> python file (missing). Good. So for --file, ext extraction should handle ".py" as py (even though positional file detection would say code). Good. So just check after last dot, regardless of before.
    if let Some((_, after)) = path.rsplit_once('.') {
        if after.is_empty() { return Lang::Python; }
        // after may contain "/"? e.g., "a.py/b"? Path "a.py/b" has last dot before slash? Actually "a.py/b" rsplit_once('.') gives ("a", "py/b"), after is "py/b" (contains slash), lowercased "py/b" not in list -> fallback python. But "a.py/b" contains slash, so positional file detection would say file (due to slash), but extension detection for --file? For --file "a.py/b" (non-existing, with slash), what lang? Likely python (fallback, since ext "py/b" unknown). Good.
        // Also after may contain spaces? e.g., "a.py " (trailing space)? After is "py " (with space), lowercased "py " not in list -> fallback python. But "a.py " as positional is code (not file), so not relevant. For --file "a.py " (with trailing space, file path with space), ext "py " -> fallback python, but file path includes trailing space. Good.
        // Need to handle after containing "/" or "\\" or maybe "?"? Just lowercased exact match.
        // Also need to handle case where after contains "/" due to path like "dir/file.py"? Actually "dir/file.py" rsplit gives ("dir/file", "py"), after "py" (no slash). Good.
        // For "a/b.c/d"? After "d"? Actually "a/b.c/d" has no dot after last slash? It has dot before slash, after is "c/d" (contains slash) -> fallback. Good.
        let low = after.to_lowercase();
        // Need to handle after with "/"? If after contains "/" or "\\", then it's not a valid extension (since dot before slash)? Actually extension should be after last dot AND after last slash? Standard: ext is after last dot that is after last slash. For "a.py/b" (dot before slash), there is no ext (since last slash after last dot). So fallback python. Our simple rsplit_once('.') would give after "py/b" (contains slash) -> fallback, which is correct. Good.
        // For "a/b.py" (dot after slash), after "py" (no slash) -> py. Good.
        // So check if after contains '/' or '\\', then fallback.
        if low.contains('/') || low.contains('\\') {
            return Lang::Python;
        }
        match low.as_str() {
            "py" | "py3" | "python" | "pyw" => Lang::Python,
            "js" | "mjs" | "cjs" | "jsx" => Lang::Javascript,
            "ts" | "tsx" => Lang::Typescript,
            "rb" => Lang::Ruby,
            "pl" | "pm" => Lang::Perl,
            "php" => Lang::Php,
            "lua" => Lang::Lua,
            "r" => Lang::R,
            "swift" => Lang::Swift,
            "kt" | "kts" => Lang::Kotlin,
            "java" => Lang::Java,
            "c" => Lang::C,
            "cpp" | "cc" | "cxx" | "hpp" | "hxx" => Lang::Cpp,
            "go" => Lang::Go,
            "rs" => Lang::Rust,
            "sh" | "bash" | "zsh" => Lang::Bash,
            "hs" => Lang::Haskell,
            "jl" => Lang::Julia,
            "dart" => Lang::Dart,
            "ex" | "exs" => Lang::Elixir,
            "groovy" => Lang::Groovy,
            "cr" => Lang::Crystal,
            "nim" => Lang::Nim,
            "cs" => Lang::Csharp,
            "zig" => Lang::Zig,
            _ => Lang::Python,
        }
    } else {
        Lang::Python
    }
}

fn detect_heuristic(code: &str) -> Lang {
    // Ordered checks (highest to lowest): rust, go, csharp, cpp, java, groovy, ts, js, ruby, kotlin, php, lua, bash, r, dart, swift, perl, julia, haskell, elixir, crystal, zig, nim, python default
    // Need exact substrings. Based on triggers, implement as contains checks (case-sensitive).
    // Rust: "fn main()" ? Or "fn main("? Test: "fn main()" -> rust, "fn main" (no parens) -> python, "fn foo()" -> python. So check "fn main("? Or "fn main()" exact? What about "fn main ()" (with space)? Need to test. For now, check "fn main(".
    // Actually need to test "fn main(" vs "fn main()". Let's assume "fn main(".
    // Go: "package main" or "func main("? Our triggers: "package main" -> go, "func main()" -> go. What about "package foo" (without main) -> groovy (not go). So go requires "package main" (with single space?) or "func main("? Need to test "package  main" (two spaces), "func  main", etc.
    // For now, implement simple contains for our triggers.
    if code.contains("fn main(") { return Lang::Rust; }
    // Go: check "package main" (single space, case-sensitive) or "func main("?
    if code.contains("package main") || code.contains("func main(") { return Lang::Go; }
    if code.contains("using System") { return Lang::Csharp; }
    // Cpp: "int main(" or "#include <" or "std::" ? Our triggers: "int main()" -> cpp, "#include <stdio.h>" -> cpp, "std::cout" -> cpp. What about "#include" without "<" -> R (not cpp). So cpp requires "#include <" (with "<")? Or "int main("? Or "std::"?
    if code.contains("int main(") || code.contains("#include <") || code.contains("std::") { return Lang::Cpp; }
    // Java: "public class" ? Our trigger "public class Main" -> java, but "class Foo" -> python, "public class" alone? Need to test. Assume "public class".
    if code.contains("public class") { return Lang::Java; }
    // Groovy: "def " + "="? Or "package foo"? Our triggers: "def x = 1" -> groovy, "package foo" -> groovy? Wait "package foo" (without main) -> groovy, but "package main" -> go (higher). So groovy check for "package " (with space) but not "package main"? Or "def "?
    // Actually "package foo" -> groovy, but "package main" -> go (higher, so go wins). So groovy check could be "package " (any) but go already checked first, so remaining "package " (without main) -> groovy. Good.
    // And "def " with "="? Our trigger "def x = 1" -> groovy, but "def foo" (without =) -> python. So groovy requires "def " + "="? Or just "def "?
    // Let's check: "def x = 1" contains "def " and "=", "def foo" contains "def " but no "=". So groovy requires both? Or "def " + "=" in same line? For now, check (code.contains("def ") && code.contains("=")) or code.contains("package ") ?
    // But "package " would also match "package main" (already handled by go, so fine).
    if (code.contains("def ") && code.contains("=")) || code.contains("package ") { return Lang::Groovy; }
    // TS: "interface " or "type " + "="? Our triggers: "interface Foo" -> ts, "type Foo =" -> ts, "import {" -> ts. Need exact: "interface " (with space), "type " ? Or "import {"?
    if code.contains("interface ") || code.contains("import {") || (code.contains("type ") && code.contains("=")) { return Lang::Typescript; }
    // JS: "console.log" or "function " or "module.exports" ? Our triggers: "console.log" -> js, "function foo()" -> js, "module.exports" -> js. Need exact.
    if code.contains("console.log") || code.contains("function ") || code.contains("module.exports") { return Lang::Javascript; }
    // Ruby: "puts " or "require \"" or "module " ? Our triggers: "puts 1" (puts + space) -> ruby, "require \"http\"" (require + space + \") -> ruby, "module Foo" (module + space) -> ruby. Need exact.
    if code.contains("puts ") || code.contains("require \"") || code.contains("module ") { return Lang::Ruby; }
    // Kotlin: "val " or "fun main" or "import ("? Our triggers: "val x=1" (val + space) -> kotlin, "fun main()" (fun main) -> kotlin, "import (" (import + space + () -> kotlin. Need exact.
    if code.contains("val ") || code.contains("fun main") || code.contains("import (") { return Lang::Kotlin; }
    // PHP: "<?php" or ("echo " + "'" or "\"")? Our triggers: "<?php" -> php, "echo 'hi'" (echo + space + ') -> php, "echo \"hi\"" -> php, "echo hi" (without quotes) -> bash (not php). So php requires "<?php" or ("echo " + quote)? Need exact: echo with quotes.
    if code.contains("<?php") || (code.contains("echo ") && (code.contains("'") || code.contains("\""))) { return Lang::Php; }
    // Lua: "print(" ? Our trigger "print(1)" -> lua. What about "print (" with space? Need to test. Assume "print(".
    if code.contains("print(") { return Lang::Lua; }
    // Bash: "echo " (without quotes? But php already checked echo with quotes, so remaining echo without quotes -> bash) or "export " or "#!/bin/bash" or "#!/bin/sh"? Our triggers: "echo hi" (echo + space, no quotes) -> bash, "export " -> bash, "#!/bin/bash" -> bash. Need exact.
    if code.contains("echo ") || code.contains("export ") || code.contains("#!/bin/bash") || code.contains("#!/bin/sh") { return Lang::Bash; }
    // R: "library(" or "require(" or code.starts_with("#")? Our triggers: "library(" -> r, "require(" -> r, "#define"/"#include"/"#pragma" (starting with #) -> r. Need exact: check "library(" or "require(" or code.trim_start().starts_with("#")? What about "#include <...>" (which is cpp, higher, already handled)? Since cpp checked earlier (#include <), remaining #... -> r. Good. So check for "#" at start? Or contains "#"? Let's check: "#define" in middle? Probably contains "#"? But "#include <...>" already handled, so remaining "#" -> r. For now, check library(/require( or trimmed starts with "#".
    if code.contains("library(") || code.contains("require(") || code.trim_start().starts_with('#') { return Lang::R; }
    // Dart: "void main(" ? Our trigger "void main()" -> dart. What about "void main" without parens -> python. So check "void main(".
    if code.contains("void main(") { return Lang::Dart; }
    // Swift: "struct " + "{"? Our trigger "struct Bar {" -> swift. What about "struct Foo" without "{" -> julia. So swift requires "struct " and "{"? Need exact.
    if code.contains("struct ") && code.contains("{") { return Lang::Swift; }
    // Perl: "print " (without "("?) or "my " + "$" or "use strict" or "sub "? Our triggers: "print 1" (print + space, no "(") -> perl, "my $x" (my + space + $) -> perl, "use strict" -> perl, "sub foo" (sub + space) -> perl. Need exact. Note: lua already checked "print(", so remaining "print " (with space, no "(") -> perl. Good.
    if code.contains("my $") || code.contains("use strict") || code.contains("sub ") || (code.contains("print ") && !code.contains("print(")) { return Lang::Perl; }
    // Julia: "println(" or "struct " (without "{"? But swift already checked struct+{, so remaining struct -> julia) or "using "? Our triggers: "println(1)" -> julia, "struct Foo" (without {) -> julia, "using Pkg" -> julia. Need exact.
    if code.contains("println(") || code.contains("struct ") || code.contains("using ") { return Lang::Julia; }
    // Haskell: "let " + "="? Or "main ="? Or "data " + "="? Our triggers: "let x = 5" (let + space, =) -> haskell, "main =" (main + space + =) -> haskell, "data Foo =" -> haskell. Need exact.
    if (code.contains("let ") && code.contains("=")) || code.contains("main =") || (code.contains("data ") && code.contains("=")) { return Lang::Haskell; }
    // Elixir: "IO." or "defmodule " + "do"? Our triggers: "IO.puts" (IO.) -> elixir, "defmodule Foo do" (defmodule + do) -> elixir. Need exact.
    if code.contains("IO.") || (code.contains("defmodule ") && code.contains(" do")) { return Lang::Elixir; }
    // Crystal: "enum " ? Our trigger "enum Foo" -> crystal. Need exact.
    if code.contains("enum ") { return Lang::Crystal; }
    // Zig: "pub fn main() !void" ? Our trigger full signature -> zig. Need exact: check "!void" or "pub fn main"?
    if code.contains("!void") { return Lang::Zig; }
    // Nim: "proc " or "var " + ":"? Our triggers: "proc foo()" (proc + space) -> nim, "var x: int" (var + space + :) -> nim. Need exact.
    if code.contains("proc ") || (code.contains("var ") && code.contains(":")) { return Lang::Nim; }
    Lang::Python
}

fn probe_dotnet() -> Result<String, String> {
    // Always run dotnet --list-sdks, return output or error (ignored for non-csharp)
    let out = ProcCommand::new("dotnet").arg("--list-sdks").output();
    match out {
        Ok(o) if o.status.success() => Ok(String::from_utf8_lossy(&o.stdout).to_string()),
        Ok(o) => Err(String::from_utf8_lossy(&o.stderr).to_string()),
        Err(e) => Err(e.to_string()),
    }
}

fn find_in_path(name: &str) -> Option<PathBuf> {
    if let Some(paths) = env::var_os("PATH") {
        for p in env::split_paths(&paths) {
            let cand = p.join(name);
            if cand.is_file() {
                // Check executable? On unix, check permissions? Simplify: exists and is file
                // Also need to check executable bit? Use metadata permissions?
                if let Ok(md) = fs::metadata(&cand) {
                    use std::os::unix::fs::PermissionsExt;
                    if md.permissions().mode() & 0o111 != 0 {
                        return Some(cand);
                    }
                }
            }
        }
    }
    None
}

fn resolve_tool(primary: &[&str]) -> Option<PathBuf> {
    for name in primary {
        if let Some(p) = find_in_path(name) {
            return Some(p);
        }
    }
    None
}

fn run_version_check(bin: &Path, args: &[&str]) -> bool {
    // Run bin --version etc., ignore output, return true if spawn succeeded (even if exit non-zero? Actually version check failure is ignored, only missing binary matters for friendly error.
    // For our purposes, version check is just to trigger friendly error if binary missing? Actually we already checked existence via find_in_path. Version check failure (non-zero) is ignored (proceed).
    // But original always runs version check (e.g., python3 --version) before execution, even if binary exists. We must replicate (run it, ignore result).
    // However, for missing binary, we don't run version (since binary not found), instead return friendly error.
    // So this function assumes binary exists, runs version, ignores result.
    let _ = ProcCommand::new(bin).args(args).output();
    true
}

