// Helper to run child and propagate exit/signal (signal->0)
fn run_child(mut cmd: ProcCommand, stdin_data: Option<&[u8]>) -> i32 {
    // Configure stdin
    if stdin_data.is_some() {
        cmd.stdin(Stdio::piped());
