// Helper to run child and propagate exit/signal (signal->0)
fn run_child(mut cmd: ProcCommand, stdin_data: Option<&[u8]>) -> i32 {
    // Configure stdin
    if stdin_data.is_some() {
        cmd.stdin(Stdio::piped());
    } else {
        // Inherit stdin? For inline/file execution with piped stdin (program input), need to inherit original stdin (which may be piped).
        // But for stdin-as-code execution (streaming), stdin_data is code (piped to interpreter), not program input.
        // For temp-file stdin execution, program stdin should be empty/closed? Or inherit? Actually for temp-file stdin execution, original stdin is code (already consumed), program stdin should be empty (not inherit, since already consumed). How to handle?
        // For inline/file with piped program input (e.g., echo hi | run --code "cat"), stdin_data is None (since code from --code, not stdin), but original stdin (piped hi) should be passed to program. So inherit.
        // For stdin-as-code with temp file (e.g., echo "print(1)" | run --lang perl), stdin_data is None? Actually code is from stdin (already read), program stdin should be empty (since stdin consumed as code). So not inherit, but empty.
        // Need to distinguish: for exec_inline/exec_file with no stdin_data (code from flag/file, not stdin), inherit original stdin (for program input).
        // For exec_stdin with temp file (code from stdin, already consumed), do NOT inherit (use null/empty).
        // For exec_stdin with streaming (code piped to interpreter), stdin_data is code (piped).
        // So caller must specify: inherit vs null vs piped.
        // For now, default inherit (for inline/file). For stdin temp, caller should use Stdio::null().
        cmd.stdin(Stdio::inherit());
    }
    cmd.stdout(Stdio::inherit());
    cmd.stderr(Stdio::inherit());
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => {
            // Spawn failure (binary missing? But we already checked existence, so this shouldn't happen for missing toolchain (we handle friendly before). For other spawn errors (e.g., permission?), what error? For js/ruby missing, original gives generic "No such file..." (from spawn). That happens when binary missing and we didn't give friendly (for js/ruby/python). So for those, we should attempt spawn with "node"/"ruby"/"python3" (unresolved?) and let it fail with generic.
            // For now, print generic and exit 1.
            eprintln!("Error: {} (os error {})", e.to_string().split(" (os error").next().unwrap_or(&e.to_string()), e.raw_os_error().unwrap_or(2));
            // Actually original for js/ruby/python missing gives "Error: No such file or directory (os error 2)" (without context). For others, friendly. So for generic langs, we should NOT check existence before, just attempt spawn and let it fail.
            // For friendly langs, we check existence and give friendly before spawn.
            // This run_child is for after checks, so spawn failure here is unexpected (e.g., compiled binary missing? For c compiled binary missing? That gives "failed to execute compiled binary..." with caused by. Need to handle separately.
            // For generic, print "Error: No such file or directory (os error 2)"? Let's just print e.
            return 1;
        }
    };
    if let Some(data) = stdin_data {
        use std::io::Write;
        if let Some(mut stdin) = child.stdin.take() {
            let _ = stdin.write_all(data);
            // Close stdin
        }
    }
    match child.wait() {
        Ok(status) => {
            if let Some(code) = status.code() {
                code
            } else if status.signal().is_some() {
                0 // signal -> 0 (as observed)
            } else {
                1
            }
        }
        Err(_) => 1,
    }
}

