fn run_child_generic(mut cmd: ProcCommand) -> i32 {
    cmd.stdin(Stdio::inherit());
    cmd.stdout(Stdio::inherit());
    cmd.stderr(Stdio::inherit());
    match cmd.spawn() {
        Ok(mut child) => {
            match child.wait() {
                Ok(s) => s.code().unwrap_or(0),
                Err(_) => 1,
            }
        }
        Err(e) => {
            // Generic error: "Error: No such file or directory (os error 2)"
            // e.to_string() is "No such file or directory (os error 2)"? Actually std::io::Error for NotFound is "No such file or directory (os error 2)". Original prints "Error: No such file or directory (os error 2)". Good.
            eprintln!("Error: {}", e);
            1
        }
    }
}

