fn exec_generic_temp_inline(lang: Lang, code: &str, prefix: &str, filename: &str, bin_names: &[&str], version_args: &[&str], run_args_fn: &dyn Fn(&PathBuf) -> Vec<String>, friendly_msg: &str) -> i32 {
